#include <stdio.h>
int main(void)
{
  int a[2][3] = {{3, 8, 1}, {6, 2, 9}};
  int i, j, s = 0, max;
  for (i = 0; i < 2; i++) {
    max = a[i][0];
    for (j = 1; j < 3; j++)
      if (a[i][j] > max) max = a[i][j];
    s += max;
  }
  printf("%d\n", s);
  return 0;
}

